import { AvatarGroup } from '@refy-design/web';
import type { AvatarGroupItem } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
const team: AvatarGroupItem[] = [
  { name: 'Joana Martins' },
  { name: 'Marcos Silva', color: 'var(--legacy-ink-2)' },
  { name: 'Renata Costa' },
  { name: 'Paulo Braga', color: 'var(--legacy-ink-2)' },
  { name: 'Ana Lúcia Prado' },
  { name: 'Caio Fernandes' },
  { name: 'Duda Rocha' },
];
export function Example() {
  const args: Pick<ComponentProps<typeof AvatarGroup>, 'items' | 'max'> = {
    items: team,
    max: 4,
  };
  const [selected, setSelected] = useState('Select a person.');
  return (
    <div style={{ display: 'grid', gap: 'var(--space-4)' }}>
      <AvatarGroup
        {...args}
        onItemClick={(item) => setSelected(`Selected person: ${item.name}`)}
        onOverflowClick={() =>
          setSelected(
            `Other members: ${args.items
              .slice(args.max ?? 4)
              .map((item) => item.name)
              .join(', ')}`,
          )
        }
      />
      <p role="status">{selected}</p>
    </div>
  );
}

import { AvatarGroup } from '@refy-design/web';
import { Drawer } from '@refy-design/web';
import { PersonCell } from '@refy-design/web';
import { useState } from 'react';
function AvatarGroupExample() {
  const team = [
    'Joana Martins',
    'Marcos Silva',
    'Renata Costa',
    'Paulo Braga',
    'Ana Prado',
    'Caio Fernandes',
    'Duda Rocha',
  ].map((name) => ({ name }));
  const [person, setPerson] = useState('');
  return (
    <>
      <AvatarGroup
        items={team}
        max={4}
        onItemClick={(item) => setPerson(item.name)}
        onOverflowClick={() => setPerson('All members')}
      />
      <Drawer
        open={Boolean(person)}
        onOpenChange={(open) => {
          if (!open) setPerson('');
        }}
        title={person}
      >
        {(person === 'All members'
          ? team
          : team.filter((item) => item.name === person)
        ).map((item) => (
          <PersonCell key={item.name} name={item.name} secondary="Team member" />
        ))}
      </Drawer>
    </>
  );
}
export function Example() {
  return <AvatarGroupExample />;
}
